-- English essays + lines + terms
INSERT INTO public.essays (
  subject_id, paper_code, title, question, content_en, content_mm, display_order, is_active
)
SELECT
  (SELECT id FROM public.subjects WHERE slug = 'english' LIMIT 1),
  NULL,
  'Actions speak louder than words',
  NULL,
  'The well-known proverb "Actions speak louder than words" emphasizes that what people do is far more important than what they say. While promises and verbal statements are easy to make, genuine character and real intentions are ultimately demonstrated through concrete actions.

First, making promises is effortless, but fulfilling them requires effort and honesty. Many people make big commitments or give spoken assurances, yet fail to follow through when difficulties arise. For example, a friend may frequently say they will help you, but their loyalty is only proven when they actually show up during a hard time. Therefore, deeds build genuine trust, whereas empty words often lead to disappointment.

Second, consistent behavior reflects true intentions better than speech. In personal relationships, workplaces, and leadership roles, people are judged by their results rather than their explanations. A leader who works hard and treats others with respect inspires far more confidence than one who only makes grand speeches without taking meaningful action.

In conclusion, words can express good intentions, but only actions provide real proof of sincerity. To build strong relationships and maintain respect, we must always ensure that our deeds align with the promises we make.',
  NULL,
  1,
  true
WHERE (SELECT id FROM public.subjects WHERE slug = 'english' LIMIT 1) IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.essays e
    WHERE e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'english' LIMIT 1)
      AND e.title = 'Actions speak louder than words'
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
