FROM public.essays e
WHERE e.title = 'Actions speak louder than words'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'english' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 1
  );

