  NULL,
  'The pen is mightier than the sword',
  NULL,
  'The famous proverb "The pen is mightier than the sword" suggests that written words and ideas have a far greater impact on society than physical violence. While a sword can force physical obedience through fear, written ideas possess the enduring power to transform minds, inspire movements, and shape human history.

First, physical force only achieves temporary control, whereas words create lasting change. Weapons can win battles, conquer lands, or destroy cities, but they cannot win hearts or change minds. In contrast, books, speeches, and articles can expose injustice and inspire people to unite for freedom. Throughout history, many political revolutions and social reforms began not with weapons, but with powerful writings that challenged corrupt rulers.

Second, the power of written words outlasts physical power. A sword can only harm a few individuals at a specific time and place. However, written ideas can travel across borders, survive through centuries, and continue to educate future generations long after the author has died.

In conclusion, violence can destroy life, but literature and ideas build civilization. Therefore, peaceful expression through writing remains humanity''s most effective tool for progress and positive change.',
  NULL,
  2,
  true
WHERE (SELECT id FROM public.subjects WHERE slug = 'english' LIMIT 1) IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.essays e
    WHERE e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'english' LIMIT 1)
      AND e.title = 'The pen is mightier than the sword'
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 1, 'The famous proverb "The pen is mightier than the sword" suggests that written words and ideas have a far greater impact on society than physical violence.', '"ဘောပင်သည် ဓားထက် ပိုမိုအားကောင်းသည်" ဟူသော ကျော်ကြားသည့် ဆိုစကားသည် ရေးသားထားသော စကားလုံးများနှင့် အတွေးအခေါ်များသည် ရုပ်ပိုင်းဆိုင်ရာ အကြမ်းဖက်မှုထက် လူ့အဖွဲ့အစည်းအပေါ် များစွာသော သက်ရောက်မှုရှိကြောင်း ညွှန်ပြသည်။'
FROM public.essays e
WHERE e.title = 'The pen is mightier than the sword'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'english' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 1
  );

