-- Philo Q&A essays + lines + terms
INSERT INTO public.essays (
  subject_id, paper_code, title, question, content_en, content_mm, display_order, is_active
)
SELECT
  (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1),
  '3101',
  'The Nature and Scope of Aesthetics',
  'Explain the nature and scope of aesthetics?',
  'Aesthetics is broader in scope than the philosophy of art, which comprises one of the branches. It deals not only with the nature and value of the arts but also with those responses to natural objects that find expression in the language of the beautiful and the ugly.

Almost anything might be seen as beautiful by someone or from some point of view. Different people apply the word to quite disparate objects for reasons. It may be that there is some single underlying belief that motivates all of their judgments. The term beautiful has no sense except as the expression of an attitude which is attached by different people to quite different states of affairs.

They are the most important or most useful either in the discussion and criticism of art or in the description of that which appeals to our nature. To convey which is significant in a poem we might use such terms as ironical, moving, expressive, balanced and harmonious.

Beautiful belongs to a class of terms from which it has been chosen as much for convenience''s sake for any sense. Aesthetics must therefore cast its net more widely than the study either of theory. What should a philosopher study in order to understand such ideas as beauty and taste?',
  NULL,
  1,
  true
WHERE (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1) IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.essays e
    WHERE e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
      AND e.title = 'The Nature and Scope of Aesthetics'
  );

