INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 5, 'It may be that there is some single underlying belief that motivates all of their judgments.', 'သူတို့၏ အဆုံးအဖြတ်အားလုံးကို လှုံ့ဆော်ပေးသော တစ်ခုတည်းသော အခြေခံယုံကြည်ချက် တစ်ခုခုရှိနိုင်သည်။'
