INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 7, 'They are the most important or most useful either in the discussion and criticism of art or in the description of that which appeals to our nature.', '၎င်းတို့သည် အနုပညာ၏ ဆွေးနွေးမှုနှင့် ဝေဖန်ရေးတွင်ဖြစ်စေ၊ ကျွန်ုပ်တို့သဘာဝကို ဆွဲဆောင်နိုင်သောအရာများကို ဖော်ပြရာတွင်ဖြစ်စေ အရေးအကြီးဆုံး သို့မဟုတ် အသုံးဝင်ဆုံးဖြစ်သည်။'
