INSERT INTO public.essays (
  subject_id, paper_code, title, question, content_en, content_mm, display_order, is_active
)
SELECT
  (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1),
  '3101',
  'Plato''s Theory of Art',
  'Q2. Theory Imitation',
  'Plato’s theory is the first, the simplest, and the oldest of art in Western thought.
The idea that poetry and painting are arts of imitation derives from Plato.
Plato’s view of art can be studied from the principle dialogues consisting of the Ion, The Symposium, The Republic, The Sophist, and The Law.

Art and Craft
He discusses : visual arts (painting, sculpture, architecture), literary arts (epic, lyric, and dramatic poetry), and mixed musical arts(dance and song).

In the Sophist, crafts are divided into “acquisitive” and “productive” the latter being subdivided into 
(1) production of actual objects, which may be either human or divine and 
(2) production of “images” which may also be human or devine (reflections and dreams by god; pictures by men.
Images, which imitate their originals but cannot fulfill their function, are further subdivided; the imitator may produce
 (1) a genuine likeness with the same properties
 (2) an apparent likeness or friendship semblance.
There is thus false imitation the making of deceptive semblances.
So all imitation is in a sense both true and untrue, has both being and nonbeing.
According to him art is closer to craft. Plato divides craft into acquisitive craft and productive craft or creative craft. Productive craft can be sub-divided into human craft and divine craft. Art is included in divine craft.',
  NULL,
  1,
  true
WHERE (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1) IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.essays e
    WHERE e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
      AND e.title = 'Plato''s Theory of Art'
  );

