SELECT e.id, 9, 'Images, which imitate their originals but cannot fulfill their function, are further subdivided; the imitator may produce', 'မူရင်းအရာဝတ္ထုများကို အတုခိုးသော်လည်း ၎င်းတို့၏ လုပ်ငန်းဆောင်တာကို မဖြည့်ဆည်းနိုင်သော ပုံရိပ်များကို ထပ်မံခွဲခြားထားသည်။ အတုခိုးသူသည် ဖန်တီးနိုင်သည်။'
FROM public.essays e
