INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 14, 'According to him art is closer to craft. Plato divides craft into acquisitive craft and productive craft or creative craft. Productive craft can be sub-divided into human craft and divine craft. Art is included in divine craft.', 'သူ၏အဆိုအရ အနုပညာသည် လက်မှုပညာနှင့် ပိုမိုနီးစပ်သည်။ ပလေတိုသည် လက်မှုပညာကို ရယူသောလက်မှုပညာ နှင့် ထုတ်လုပ်သောလက်မှုပညာ သို့မဟုတ် ဖန်တီးသောလက်မှုပညာဟူ၍ ခွဲခြားထားသည်။ ထုတ်လုပ်သောလက်မှုပညာကို လူသားလက်မှုပညာနှင့် ဘုရားသခင်၏ လက်မှုပညာဟူ၍ ထပ်မံခွဲခြားနိုင်သည်။ အနုပညာကို ဘုရားသခင်၏ လက်မှုပညာတွင် ထည့်သွင်းထားသည်။'
FROM public.essays e
WHERE e.title = 'Plato''s Theory of Art'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 14
  );

