INSERT INTO public.essays (
  subject_id, paper_code, title, question, content_en, content_mm, display_order, is_active
)
SELECT
  (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1),
  '3107',
  'Saya Zeyya''s view on Art',
  'Q3.Evaluate Saya Zeyya''s view on Art',
  NULL,
  'ဆရာဇေယျသည် “ရူပရခြင်း” နှင့် “စိတ္တကုံးနှုန်းမှုခြင်း” ဟူသော အကြောင်းနှစ်ရပ်ကို အနုပညာနှင့်နှိုင်းယှဉ်ဖော်ပြခဲ့သည်။ သတ်မှတ်ခဲ့ပါသည်။ အနုပညာလက်ရာတစ်ခုသည် လူသားတစ်ဦးဖြစ်စေ၊ သဘာဝကြည်ညိုဖွယ်ရာဖြစ်စေ၊ ဒီအနုပညာလက်ရာကို ရှုမြင်ခြင်းနှင့် စိတ်တွေး လှုံ့ဆော်ခြင်းတို့သာ အဓိကဖြစ်သည်ဟုဆိုပါသည်။

အနုပညာတန်ဖိုးနှင့်စပ်လျဉ်းသော အမြင်
ဆရာဇေယျသည် ဇေသင်းပါးအတတ်များမှ အနုပညာ၏ တာဝန်နှင့်စပ်လျဉ်းသော အမြင်ကို တင်ပြခဲ့ပါသည်။ ဆရာက အနုပညာ၏တာဝန်သည် “အလှနှင့်ပတ်သက်သော လူ့အလိုကို ဖြည့်စွမ်းပေးရန်ဖြစ်သည်။” ဟု ဆိုခဲ့ပါသည်။ သဘာဝသည် လှ၏။ လူသည် အလှကို အလိုရှိ၏။ ကြိုက်နှစ်သက်၏။ အမြင်လည် တွေ့လိုက်ရ၏။ ထာဝစဉ်ပိုင်ဆိုင်ချင်၏။ ထို့ကြောင့် သဘာဝအလှသည် အမြဲတည်မနေ ပြောင်းလဲတတ်၏။ ပျောက်ကွယ်တတ်၏။

လူခြင်းနှင့် စပ်လျဉ်းသော အမြင်
ဆရာဇေယျက အနုပညာနှင့် လူခြင်းသည် ခွဲခြားရသောအရာများ မဟုတ်ပါ။ လူခြင်းသည် သန့်စင်သောအရာဖြစ်သည်။ လူတို့၏ စိတ်တွင် ညစ်နွမ်းသောအရာတို့ကို ဆေးကြောသုတ်သင်လျက် ဖြူစင်သန့်ရှင်းသော ဘဝ (ဂ) မြင့်မြတ်သော အဆင့်သို့ ရောက်ရှိစေသော အရာဖြစ်သည်။ မြင်ရသူတို့၏ စိတ်ကို နှစ်သက်ဝမ်းသာစေသောအရာ ဖြစ်သည်။

ဆရာဇေယျ၏အလိုအရ လူခြင်းကို သိရှိခြင်းနှင့် အနုပညာ၏ သဘောသဘာဝ၊ ရသဟ် သဘောသဘာဝကို နားလည်မှုတို့သည် မြူးနှုန်းတို့ကို စင်ကြယ်စေခြင်းရှိ၏ ကြည့်အပ်သည်ဟု ဆိုခဲ့သည်။ ဤတွင် ကာမဂုဏ်တည်းဟူသော မြူးနှုန်းတို့ကို စင်ကြယ်စေခြင်းရှိ၏ ကြည့်ရန် ဖြစ်နိုင်ပါမည်လော။ မေးစရာရှိလာပါသည်။ ထိုအခြေနှင့် စပ်လျဉ်း၍ ဆရာဇေယျက ဖြစ်နိုင်ပါသည်။ အဖြေပေးခဲ့ပါသည်။ ထိုအမြင်သည် ရသပညာသုခမိန်၌ ထူးခြားသော အမြင်ဖြစ်သည်ဟု ဆိုနိုင်ပါသည်။',
  1,
  true
WHERE (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1) IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.essays e
    WHERE e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
      AND e.title = 'Saya Zeyya''s view on Art'
  );

INSERT INTO public.essays (
  subject_id, paper_code, title, question, content_en, content_mm, display_order, is_active
)
SELECT
  (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1),
  '3107',
  'The General Sketch of Indian Aesthetics',
  'Explain the general sketch of indian aesthetics.',
  'The general sketch of Indian Aesthetics

Indian Aesthetics is based on the works of poetics . there are no classics of other fine arts, such as music, dancing, painting, sculpture etc.
All forms of art go hand in hand. So an appreciation of Indian aesthetics requires an understanding of all forms of art.
There is a surprising degree of consensus about the nature and importance of aesthetics and aesthetic pleasure (rasa).
Like truth and goodness, rasa belongs to reason (buddhi), Its relation to truth remains a major vein of speculation. The specific role that rasa plays in the human psyche.
The second basic concept of Indian aesthetics is karma, the pursuit of love and enjoyment.
Kama includes refined aesthetic pleasure, sexual pleasure, and love of the divine.
The perfect example of karma is found in the love of the divine Krishna and Radha.
There are some important features of Natya Sastra and they are, the recognition of dance, music and drama as works of art.
Natya Sastra was in the nature of encyclopedia on arts i.e. dance, drama and music.
According to Bharata, emotion (rasa, meaning “flavor” or “relish”) is recognized as the heart of drama and all art.
Rasa thus came to mean the feeling that a poet conveys to a sympathetic reader, aesthetic taste.
Rasa, the aesthetic rapture accompanying the appreciation of dance and drama, is mentioned in the Upanishads.',
  NULL,
  1,
  true
WHERE (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1) IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.essays e
    WHERE e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
      AND e.title = 'The General Sketch of Indian Aesthetics'
  );

