INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 2, 'All forms of art go hand in hand. So an appreciation of Indian aesthetics requires an understanding of all forms of art.', 'အနုပညာပုံစံအားလုံးသည် ယှဉ်တွဲတည်ရှိကြသည်။ ထို့ကြောင့် အိန္ဒိယအလှအပဗေဒကို တန်ဖိုးထားရန် အနုပညာပုံစံအားလုံးကို နားလည်ရန် လိုအပ်သည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 2
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 3, 'There is a surprising degree of consensus about the nature and importance of aesthetics and aesthetic pleasure (rasa).', 'အလှအပဗေဒနှင့် အလှအပဆိုင်ရာ သာယာမှု (ရသ) ၏ သဘောသဘာဝနှင့် အရေးပါမှုနှင့် ပတ်သက်၍ အံ့အားသင့်ဖွယ် သဘောတူညီမှုတစ်ခု ရှိသည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 3
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 4, 'Like truth and goodness, rasa belongs to reason (buddhi), Its relation to truth remains a major vein of speculation. The specific role that rasa plays in the human psyche.', 'အမှန်တရားနှင့် ကောင်းမှုတရားကဲ့သို့ပင် ရသသည် ဆင်ခြင်တုံတရား (ဗုဒ္ဓိ) နှင့် သက်ဆိုင်သည်။ အမှန်တရားနှင့် ၎င်း၏ ဆက်စပ်မှုသည် ကြီးမားသော ထင်မြင်ယူဆမှုတစ်ခု ဖြစ်နေဆဲဖြစ်သည်။ လူ့စိတ်အတွင်း ရသ၏ တိကျသောအခန်းကဏ္ဍ။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 4
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 5, 'The second basic concept of Indian aesthetics is karma, the pursuit of love and enjoyment.', 'အိန္ဒိယအလှအပဗေဒ၏ ဒုတိယအခြေခံသဘောတရားမှာ ကမာ (ကာမ) ဖြစ်ပြီး ချစ်ခြင်းနှင့် ပျော်မွေ့ခြင်းကို လိုက်စားခြင်းဖြစ်သည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 5
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 6, 'Kama includes refined aesthetic pleasure, sexual pleasure, and love of the divine.', 'ကာမတွင် သန့်စင်သော အလှအပဆိုင်ရာ သာယာမှု၊ လိင်ဆိုင်ရာ သာယာမှုနှင့် ဘုရားသခင်ကို ချစ်ခြင်းတို့ ပါဝင်သည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 6
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 7, 'The perfect example of karma is found in the love of the divine Krishna and Radha.', 'ကာမ၏ ပြီးပြည့်စုံသော ဥပမာကို ဘုရားသခင် ကရိဿနာနှင့် ရာဓတို့၏ ချစ်ခြင်းတွင် တွေ့ရှိရသည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 7
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 8, 'There are some important features of Natya Sastra and they are, the recognition of dance, music and drama as works of art.', 'နာဋျသာသန (Natya Sastra) ၏ အရေးကြီးသော အင်္ဂါရပ်များရှိပြီး ၎င်းတို့မှာ အက၊ ဂီတနှင့် ပြဇာတ်တို့ကို အနုပညာလက်ရာများအဖြစ် အသိအမှတ်ပြုခြင်းဖြစ်သည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 8
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 9, 'Natya Sastra was in the nature of encyclopedia on arts i.e. dance, drama and music.', 'နာဋျသာသနသည် အနုပညာ (အက၊ ပြဇာတ်နှင့် ဂီတ) ဆိုင်ရာ စွယ်စုံကျမ်းသဘောသဘာဝရှိသည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 9
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 10, 'According to Bharata, emotion (rasa, meaning “flavor” or “relish”) is recognized as the heart of drama and all art.', 'ဘရတ (Bharata) ၏အဆိုအရ စိတ်ခံစားမှု (ရသ၊ အဓိပ္ပာယ် "အရသာ" သို့မဟုတ် "အရသာခံစားမှု") ကို ပြဇာတ်နှင့် အနုပညာအားလုံး၏ နှလုံးသားအဖြစ် အသိအမှတ်ပြုသည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 10
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 11, 'Rasa thus came to mean the feeling that a poet conveys to a sympathetic reader, aesthetic taste.', 'ထို့ကြောင့် ရသသည် ကဗျာဆရာတစ်ဦးက စာဖတ်သူတစ်ဦးထံသို့ ပေးပို့သော ခံစားချက်၊ အလှအပဆိုင်ရာ အရသာကို ဆိုလိုလာသည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 11
  );

INSERT INTO public.essay_lines (essay_id, line_number, line_en, line_mm)
SELECT e.id, 12, 'Rasa, the aesthetic rapture accompanying the appreciation of dance and drama, is mentioned in the Upanishads.', 'အက၊ ပြဇာတ်များကို တန်ဖိုးထားခြင်းနှင့်အတူ လိုက်ပါလာသော အလှအပဆိုင်ရာ ပီတိ (ရသ) ကို ဥပနိသျှဒ်များတွင် ဖော်ပြထားသည်။'
FROM public.essays e
WHERE e.title = 'The General Sketch of Indian Aesthetics'
  AND e.subject_id = (SELECT id FROM public.subjects WHERE slug = 'philo' LIMIT 1)
  AND NOT EXISTS (
    SELECT 1 FROM public.essay_lines l
    WHERE l.essay_id = e.id AND l.line_number = 12
  );

